"""One-run fixer 3 for SpillThePaper: Gemini 3.8 Flash by default, automatic fallback to the next model / Groq
on quota errors, readable AI error messages, 'Upload my solution' buttons no longer look disabled.
Run it ONCE from the project folder (the one that contains the folders src and app), AFTER fixers 1 and 2
(works on the merged branch too):

    python apply_fixes3.py

It checks everything first and changes nothing if anything does not match. Afterwards delete it."""
import pathlib, sys

ROOT = pathlib.Path.cwd()
NEW_FILES = {
    'tests/test_solution_jobs.py': '"""Solutions written in the background while the student reads the paper."""\nimport threading\nimport time\n\nfrom src.inference.solution_jobs import WAITING, SolutionJob\nfrom src.inference.solutions import SolutionService\n\nPAPER = {"subject": "CN", "questions": [\n    {"number": 1, "text": "Explain TCP congestion control in detail.", "marks": 5, "solution": "From the paper.",\n     "solution_source": "inline", "low_quality": False},\n    {"number": 2, "text": "Explain how UDP differs from TCP in detail.", "marks": 5, "solution": None, "low_quality": False},\n    {"number": 3, "text": "Describe the three way handshake step by step.", "marks": 5, "solution": None, "low_quality": False},\n    {"number": 4, "text": "x ?? ??? garbled scan text here", "marks": 5, "solution": None, "low_quality": True}]}\n\n\nclass Slow:\n    available, model = True, "m"\n\n    def __init__(self, delay=0.15, fail_on=None):\n        self.delay, self.fail_on, self.threads, self.gate = delay, fail_on, set(), threading.Event()\n\n    def complete(self, system, user, max_tokens=1200):\n        self.threads.add(threading.current_thread().name)\n        self.gate.wait(2)\n        time.sleep(self.delay)\n        if self.fail_on and self.fail_on in user:\n            raise RuntimeError("quota")\n        return \'{"solution": "Answer for: \' + user.split("Question:")[1].strip()[:20] + \'", "marking_scheme": null}\'\n\n\nclass Off:\n    available, model = False, "none"\n\n\ndef wait(job, seconds=10):\n    end = time.time() + seconds\n    while job.pending and time.time() < end:\n        time.sleep(0.02)\n\n\ndef test_archive_is_instant_and_the_ai_fills_the_rest_in_parallel(tmp_path):\n    ai = Slow()\n    job = SolutionJob(SolutionService(ai, tmp_path), PAPER)\n    first = job.snapshot()\n    assert first[0]["source"] == "archive" and first[0]["number"] == 1\n    assert first[1]["source"] == "none" and first[1]["note"] == WAITING and job.pending == 2 and job.total_ai == 2\n    assert "garbled" in first[3]["note"] and first[3]["note"] != WAITING                 # bad scans are not attempted\n    ai.gate.set()\n    wait(job)\n    done = job.snapshot()\n    assert job.pending == 0 and done[1]["source"] == "ai" and done[2]["source"] == "ai"\n    assert done[1]["text"].startswith("Answer for: Explain how UDP") and len(ai.threads) == 2   # two threads at once\n\n\ndef test_second_job_is_served_from_the_disk_cache(tmp_path):\n    ai = Slow(delay=0.01)\n    ai.gate.set()\n    wait(SolutionJob(SolutionService(ai, tmp_path), PAPER))\n    ai2 = Slow()\n    ai2.gate.set()\n    job = SolutionJob(SolutionService(ai2, tmp_path), PAPER)\n    wait(job)\n    assert not ai2.threads and all(e["source"] in ("archive", "ai", "none") for e in job.snapshot())\n    assert job.snapshot()[1]["source"] == "ai"\n\n\ndef test_failures_are_reported_not_cached_and_do_not_stop_the_others(tmp_path):\n    ai = Slow(fail_on="UDP")\n    ai.gate.set()\n    job = SolutionJob(SolutionService(ai, tmp_path), PAPER)\n    wait(job)\n    s = job.snapshot()\n    assert s[1]["source"] == "none" and "could not write" in s[1]["note"] and "again" in s[1]["note"] and s[2]["source"] == "ai"\n    again = Slow(fail_on="nothing")\n    again.gate.set()\n    job2 = SolutionJob(SolutionService(again, tmp_path), PAPER)\n    wait(job2)\n    assert job2.snapshot()[1]["source"] == "ai"                                          # retried next time\n\n\ndef test_without_a_key_nothing_is_waiting_and_the_note_says_so(tmp_path):\n    job = SolutionJob(SolutionService(Off(), tmp_path), PAPER)\n    s = job.snapshot()\n    assert job.pending == 0 and job.total_ai == 0 and s[1]["source"] == "none"\n    assert "switched off (no API key is set)" in s[1]["note"] and s[0]["source"] == "archive"\n',
    'src/inference/llm.py': '"""Language-model client for AI-written solutions. Plain HTTPS through `requests`: nothing extra\nto install, and several providers work (Gemini, Groq, Mistral, Anthropic).\n\nConfiguration = environment variables. NEVER put a key in the code, in a file that is committed,\nor in a chat message.\n\n    GEMINI_API_KEY   or  GROQ_API_KEY  or  MISTRAL_API_KEY  or  ANTHROPIC_API_KEY\n    LLM_PROVIDER     optional: gemini | groq | mistral | anthropic\n                     (default: the first of these whose key is set, in this order)\n    LLM_VISION_MODEL optional: model that reads photos (default: Gemini/Anthropic read photos with\n                     the normal model; Groq/Mistral use the model named in VISION_MODELS below)\n    LLM_MODEL        optional: model name for the main provider (see the defaults below; model\n                     names change, if a request says "model not found" copy a current name from\n                     the provider\'s dashboard)\n    GEMINI_MODEL / GROQ_MODEL / MISTRAL_MODEL / ANTHROPIC_MODEL\n                     optional: model name of one provider (wins over LLM_MODEL for that provider)\n\nIf the main provider fails (quota, busy, wrong model) the client tries the next model of the same\nprovider (FALLBACK_MODELS, its own quota) and then every other provider whose key is set, so a\nGroq key next to the Gemini key is a safety net.\n\nWindows PowerShell (this window only):   $env:GEMINI_API_KEY = "paste-key-here"\nCheck that it works:                     python -m src.inference.llm\n\nThe rest of the app only needs `.available`, `.model` and `.complete(system, user, max_tokens)`.\nEvery failure (no internet, timeout, quota, bad key, empty answer) is raised as LLMError with a\nreadable message, so a page can show it instead of crashing."""\nfrom __future__ import annotations\n\nimport base64\nimport os\nimport time\n\nimport requests\n\ntry:                                     # optional: read keys from a .env file in the project folder\n    from dotenv import load_dotenv\n    load_dotenv()\nexcept ImportError:\n    pass\n\n# provider -> (API key variable, URL, default model, wire format)\nPROVIDERS = {\n    "gemini": ("GEMINI_API_KEY",\n               "https://generativelanguage.googleapis.com/v1beta/openai/chat/completions",\n               "gemini-3.8-flash", "openai"),\n    "groq": ("GROQ_API_KEY", "https://api.groq.com/openai/v1/chat/completions",\n             "llama-3.3-70b-versatile", "openai"),\n    "mistral": ("MISTRAL_API_KEY", "https://api.mistral.ai/v1/chat/completions",\n                "mistral-small-latest", "openai"),\n    "anthropic": ("ANTHROPIC_API_KEY", "https://api.anthropic.com/v1/messages",\n                  "claude-sonnet-5-5", "anthropic"),\n}\n# Model used to READ IMAGES (handwritten answers). None = the normal model also reads images.\n# Names change: if a request says "model not found", set LLM_VISION_MODEL to a current vision model.\nVISION_MODELS = {"gemini": None, "anthropic": None,\n                 "groq": "meta-llama/llama-4-scout-17b-16e-instruct", "mistral": "pixtral-12b-2409"}\n# Second choice of the SAME provider (each Gemini model has its own free quota)\nFALLBACK_MODELS = {"gemini": ["gemini-3.5-flash-lite"], "groq": ["openai/gpt-oss-20b"]}\nMODEL_ENV = {"gemini": "GEMINI_MODEL", "groq": "GROQ_MODEL", "mistral": "MISTRAL_MODEL",\n             "anthropic": "ANTHROPIC_MODEL"}\nRETRY_STATUS = (429, 500, 502, 503, 504, 529)\nMAX_WAIT_S = 20\n\n\nclass LLMError(RuntimeError):\n    pass\n\n\ndef pick_provider(env=None) -> str | None:\n    env = os.environ if env is None else env\n    wanted = (env.get("LLM_PROVIDER") or "").strip().lower()\n    if wanted:\n        if wanted not in PROVIDERS:\n            raise LLMError(f"LLM_PROVIDER={wanted!r} is not one of {\', \'.join(PROVIDERS)}")\n        return wanted\n    return next((p for p, spec in PROVIDERS.items() if env.get(spec[0])), None)\n\n\nclass LLMClient:\n    def __init__(self, provider: str | None = None, api_key: str | None = None,\n                 model: str | None = None, timeout: int = 90):\n        self.provider = provider or pick_provider() or ("anthropic" if api_key else None)\n        self.api_key = api_key or (os.environ.get(PROVIDERS[self.provider][0], "")\n                                   if self.provider else "")\n        default_model = PROVIDERS[self.provider][2] if self.provider else ""\n        main = pick_provider() if self.provider else None\n        generic = os.environ.get("LLM_MODEL") if self.provider == main else None   # LLM_MODEL = main provider only\n        self.model = (model or (os.environ.get(MODEL_ENV[self.provider], "").strip() if self.provider else "")\n                      or generic or default_model)\n        self.timeout = timeout\n        self._single = False               # True for the helper clients used inside the fallback chain\n\n    @property\n    def available(self) -> bool:\n        return bool(self.provider and self.api_key)\n\n    def describe(self) -> str:\n        if not self.available:\n            return "no API key set"\n        extra = [f"{c.provider} / {c.model}" for c in self._chain()[1:]]\n        return f"{self.provider} / {self.model}" + (f"  (then: {\', \'.join(extra)})" if extra else "")\n\n    def _chain(self) -> list:\n        """Clients to try in order: this one, the fallback model(s) of its provider, other providers with a key."""\n        if self._single:\n            return [self]\n        out = [self]\n        seen = {(self.provider, self.model)}\n\n        def add(provider, key, model):\n            if (provider, model) not in seen and key:\n                seen.add((provider, model))\n                c = LLMClient(provider=provider, api_key=key, model=model, timeout=self.timeout)\n                c._single = True\n                out.append(c)\n        for m in FALLBACK_MODELS.get(self.provider, []):\n            add(self.provider, self.api_key, m)\n        for prov, spec in PROVIDERS.items():\n            if prov != self.provider:\n                key = os.environ.get(spec[0], "")\n                add(prov, key, os.environ.get(MODEL_ENV[prov], "").strip() or spec[2])\n                for m in FALLBACK_MODELS.get(prov, []):\n                    add(prov, key, m)\n        return out\n\n    def _run(self, call):\n        """Try every client of the chain; raise one readable LLMError if all fail."""\n        errors = []\n        for c in self._chain():\n            try:\n                return call(c)\n            except LLMError as e:\n                errors.append(f"{c.provider}/{c.model}: {e}")\n        raise LLMError(errors[0] if len(errors) == 1 else\n                       "every AI model failed - " + " | ".join(errors))\n\n    # -------------------------------------------------------------------- request\n    def _request(self, system: str, user: str, max_tokens: int):\n        key_var, url, _default, wire = PROVIDERS[self.provider]\n        if wire == "anthropic":\n            headers = {"x-api-key": self.api_key, "anthropic-version": "2023-06-01",\n                       "content-type": "application/json"}\n            body = {"model": self.model, "max_tokens": max_tokens, "system": system,\n                    "messages": [{"role": "user", "content": user}]}\n        else:\n            headers = {"Authorization": f"Bearer {self.api_key}", "content-type": "application/json"}\n            # Gemini\'s newer models spend part of the budget on hidden "thinking": leave room\n            budget = max_tokens * 3 if self.provider == "gemini" else max_tokens\n            body = {"model": self.model, "max_tokens": budget, "temperature": 0.2,\n                    "messages": [{"role": "system", "content": system},\n                                 {"role": "user", "content": user}]}\n        return url, headers, body, wire\n\n    @staticmethod\n    def _text(data: dict, wire: str) -> str:\n        try:\n            if wire == "anthropic":\n                return "".join(b.get("text", "") for b in data.get("content", [])\n                               if b.get("type") == "text").strip()\n            return (data["choices"][0]["message"].get("content") or "").strip()\n        except (KeyError, IndexError, TypeError, AttributeError):\n            return ""\n\n    def _send(self, url: str, headers: dict, body: dict, wire: str) -> str:\n        """POST with retries; returns the answer text or raises LLMError with a readable message."""\n        last = ""\n        for attempt in range(3):\n            try:\n                r = requests.post(url, json=body, headers=headers, timeout=self.timeout)\n            except requests.RequestException as e:          # no internet, timeout, DNS ...\n                last = f"{type(e).__name__}"\n                time.sleep(min(2 * (attempt + 1), MAX_WAIT_S))\n                continue\n            if r.status_code == 200:\n                try:\n                    text = self._text(r.json(), wire)\n                except ValueError:\n                    text = ""\n                if not text:\n                    raise LLMError(f"{self.provider} returned an empty answer (try again, or set "\n                                   "LLM_MODEL to another model)")\n                return text\n            last = f"{r.status_code}: {r.text[:200]}"\n            if r.status_code in RETRY_STATUS and attempt < (1 if r.status_code == 429 else 2):\n                try:\n                    wait = float(r.headers.get("retry-after", 2 * (attempt + 1)))\n                except ValueError:\n                    wait = 2 * (attempt + 1)\n                time.sleep(min(wait, MAX_WAIT_S))\n                continue\n            break\n        if last.startswith(("401", "403")):\n            msg = f"the API key was refused ({last[:3]}) - check the API key"\n        elif last.startswith("404"):\n            msg = "model not found (404) - set LLM_MODEL (or LLM_VISION_MODEL) to a current model name"\n        elif last.startswith("429"):\n            msg = "quota or rate limit reached (429) - wait a minute and try again"\n        else:\n            msg = f"request failed ({last})"\n        raise LLMError(f"the {self.provider} {msg}")\n\n    def complete(self, system: str, user: str, max_tokens: int = 1200) -> str:\n        if not self.available:\n            raise LLMError("no API key is set (GEMINI_API_KEY, GROQ_API_KEY, MISTRAL_API_KEY or "\n                           "ANTHROPIC_API_KEY)")\n        if self._single:\n            return self._complete_one(system, user, max_tokens)\n        return self._run(lambda c: c._complete_one(system, user, max_tokens))\n\n    def _complete_one(self, system: str, user: str, max_tokens: int) -> str:\n        if not self.available:\n            raise LLMError("no API key is set (GEMINI_API_KEY, GROQ_API_KEY, MISTRAL_API_KEY or "\n                           "ANTHROPIC_API_KEY)")\n        url, headers, body, wire = self._request(system, user, max_tokens)\n        return self._send(url, headers, body, wire)\n\n    # ------------------------------------------------------------------- photos\n    @property\n    def vision_model(self) -> str:\n        env = os.environ.get("LLM_VISION_MODEL")\n        if env:\n            return env\n        v = VISION_MODELS.get(self.provider)\n        return self.model if v is None else v\n\n    @property\n    def supports_vision(self) -> bool:\n        return bool(self.available and self.vision_model)\n\n    def complete_vision(self, system: str, user: str, images: list, max_tokens: int = 2500) -> str:\n        """Like complete(), with photos: images = [(mime_type, bytes), ...] (jpeg or png)."""\n        if not self.available:\n            raise LLMError("no API key is set (GEMINI_API_KEY, GROQ_API_KEY, MISTRAL_API_KEY or "\n                           "ANTHROPIC_API_KEY)")\n        if self._single:\n            return self._vision_one(system, user, images, max_tokens)\n        return self._run(lambda c: c._vision_one(system, user, images, max_tokens)\n                         if c.supports_vision else (_ for _ in ()).throw(LLMError("no vision model")))\n\n    def _vision_one(self, system: str, user: str, images: list, max_tokens: int) -> str:\n        if not self.available:\n            raise LLMError("no API key is set (GEMINI_API_KEY, GROQ_API_KEY, MISTRAL_API_KEY or "\n                           "ANTHROPIC_API_KEY)")\n        if not images:\n            raise LLMError("no image was given")\n        key_var, url, _default, wire = PROVIDERS[self.provider]\n        enc = [(mime, base64.b64encode(data).decode("ascii")) for mime, data in images]\n        if wire == "anthropic":\n            headers = {"x-api-key": self.api_key, "anthropic-version": "2023-06-01",\n                       "content-type": "application/json"}\n            content = [{"type": "image", "source": {"type": "base64", "media_type": m, "data": b}}\n                       for m, b in enc] + [{"type": "text", "text": user}]\n            body = {"model": self.vision_model, "max_tokens": max_tokens, "system": system,\n                    "messages": [{"role": "user", "content": content}]}\n        else:\n            headers = {"Authorization": f"Bearer {self.api_key}", "content-type": "application/json"}\n            content = [{"type": "text", "text": user}] + [\n                {"type": "image_url", "image_url": {"url": f"data:{m};base64,{b}"}} for m, b in enc]\n            budget = max_tokens * 3 if self.provider == "gemini" else max_tokens\n            body = {"model": self.vision_model, "max_tokens": budget, "temperature": 0.0,\n                    "messages": [{"role": "system", "content": system},\n                                 {"role": "user", "content": content}]}\n        return self._send(url, headers, body, wire)\n\n\ndef main():\n    """python -m src.inference.llm   -> sends one tiny question and prints the answer or the error"""\n    try:\n        c = LLMClient()\n        print("provider / model:", c.describe())\n        if not c.available:\n            print("Set one key first, e.g. in PowerShell:  $env:GEMINI_API_KEY = \\"your-key\\"")\n            return\n        print("answer:", c.complete("Answer in one short sentence.",\n                                    "What is the time complexity of binary search?", 200))\n    except LLMError as e:\n        print("FAILED:", e)\n\n\nif __name__ == "__main__":\n    main()',
    'tests/test_llm.py': '"""The language-model client: provider choice, request format, retries and readable errors.\nNo network and no key are needed: requests.post is replaced by a fake."""\nimport json\n\nimport pytest\nimport requests\n\nfrom src.inference import llm as L\nfrom src.inference.llm import LLMClient, LLMError, pick_provider\nfrom src.inference.solutions import SolutionService\n\nKEYS = ("GEMINI_API_KEY", "GROQ_API_KEY", "MISTRAL_API_KEY", "ANTHROPIC_API_KEY", "LLM_PROVIDER", "LLM_MODEL")\n\n\n@pytest.fixture(autouse=True)\ndef clean_env(monkeypatch):\n    for v in KEYS:\n        monkeypatch.delenv(v, raising=False)\n    monkeypatch.setattr(L.time, "sleep", lambda s: None)\n\n\nclass Resp:\n    def __init__(self, code=200, body=None, headers=None, text=None):\n        self.status_code, self._body, self.headers = code, body, headers or {}\n        self.text = text if text is not None else json.dumps(body)\n\n    def json(self):\n        if self._body is None:\n            raise ValueError("not json")\n        return self._body\n\n\ndef openai_reply(text):\n    return Resp(200, {"choices": [{"message": {"content": text}}]})\n\n\ndef test_provider_choice(monkeypatch):\n    assert pick_provider({}) is None and LLMClient().available is False\n    assert pick_provider({"GROQ_API_KEY": "x", "MISTRAL_API_KEY": "y"}) == "groq"        # first set key wins\n    assert pick_provider({"GEMINI_API_KEY": "x", "GROQ_API_KEY": "y"}) == "gemini"\n    assert pick_provider({"GEMINI_API_KEY": "x", "LLM_PROVIDER": "mistral"}) == "mistral"\n    with pytest.raises(LLMError, match="LLM_PROVIDER"):\n        pick_provider({"LLM_PROVIDER": "chatgpt"})\n    monkeypatch.setenv("GROQ_API_KEY", "k")\n    c = LLMClient()\n    assert c.available and c.provider == "groq" and c.model == "llama-3.3-70b-versatile"\n    monkeypatch.setenv("LLM_MODEL", "my-model")\n    assert LLMClient().model == "my-model"\n    monkeypatch.delenv("GROQ_API_KEY")\n    assert LLMClient(api_key="k").provider == "anthropic"                                # old behaviour\n\n\n@pytest.mark.parametrize("provider, host", [("gemini", "generativelanguage.googleapis.com"),\n                                            ("groq", "api.groq.com"), ("mistral", "api.mistral.ai")])\ndef test_openai_style_providers(monkeypatch, provider, host):\n    sent = {}\n\n    def post(url, json=None, headers=None, timeout=None):\n        sent.update(url=url, body=json, headers=headers)\n        return openai_reply("  the answer  ")\n    monkeypatch.setattr(L.requests, "post", post)\n    c = LLMClient(provider=provider, api_key="secret")\n    assert c.complete("be brief", "question?", 1000) == "the answer"\n    assert host in sent["url"] and sent["headers"]["Authorization"] == "Bearer secret"\n    assert sent["body"]["messages"][0] == {"role": "system", "content": "be brief"}\n    assert sent["body"]["messages"][1]["content"] == "question?" and sent["body"]["model"] == c.model\n    assert sent["body"]["max_tokens"] == (3000 if provider == "gemini" else 1000)\n\n\ndef test_retry_after_then_success(monkeypatch):\n    replies = iter([Resp(429, {"e": 1}, {"retry-after": "3"}), Resp(503, {"e": 1}), openai_reply("ok")])\n    monkeypatch.setattr(L.requests, "post", lambda *a, **k: next(replies))\n    assert LLMClient(provider="groq", api_key="k").complete("s", "u") == "ok"\n\n\n@pytest.mark.parametrize("reply, hint", [\n    (Resp(401, {"e": 1}), "check the API key"),\n    (Resp(404, {"e": 1}), "LLM_MODEL"),\n    (Resp(429, {"e": 1}), "rate limit"),\n])\ndef test_http_errors_have_readable_messages(monkeypatch, reply, hint):\n    monkeypatch.setattr(L.requests, "post", lambda *a, **k: reply)\n    with pytest.raises(LLMError, match=hint):\n        LLMClient(provider="gemini", api_key="k").complete("s", "u")\n\n\ndef test_network_failures_become_llm_errors(monkeypatch):\n    calls = []\n\n    def boom(*a, **k):\n        calls.append(1)\n        raise requests.ConnectionError("no internet")\n    monkeypatch.setattr(L.requests, "post", boom)\n    with pytest.raises(LLMError, match="ConnectionError"):\n        LLMClient(provider="mistral", api_key="k").complete("s", "u")      # mistral has no fallback model\n    assert len(calls) == 3\n    monkeypatch.setattr(L.requests, "post", lambda *a, **k: (_ for _ in ()).throw(requests.Timeout()))\n    with pytest.raises(LLMError):\n        LLMClient(provider="groq", api_key="k").complete("s", "u")\n\n\n@pytest.mark.parametrize("reply", [Resp(200, {"choices": []}), Resp(200, {"choices": [{"message": {"content": None}}]}),\n                                   Resp(200, None, text="<html>"), Resp(200, {"unexpected": True}),\n                                   openai_reply("   ")])\ndef test_empty_or_malformed_answers(monkeypatch, reply):\n    monkeypatch.setattr(L.requests, "post", lambda *a, **k: reply)\n    with pytest.raises(LLMError, match="empty answer"):\n        LLMClient(provider="mistral", api_key="k").complete("s", "u")\n\n\ndef test_a_failing_llm_never_crashes_the_solution_page(monkeypatch, tmp_path):\n    q = {"number": 1, "text": "Explain TCP congestion control in detail.", "marks": 5, "solution": None,\n         "low_quality": False, "topic_label": "tcp"}\n    monkeypatch.setattr(L.requests, "post", lambda *a, **k: (_ for _ in ()).throw(requests.ConnectionError()))\n    r = SolutionService(LLMClient(provider="groq", api_key="k"), tmp_path).solve("CN", q)\n    assert r["source"] == "none" and "failed" in r["note"]\n    monkeypatch.setattr(L.requests, "post", lambda *a, **k: openai_reply(""))   # empty: say so, do not cache\n    svc = SolutionService(LLMClient(provider="groq", api_key="k"), tmp_path)\n    assert svc.solve("CN", q)["source"] == "none"\n    monkeypatch.setattr(L.requests, "post", lambda *a, **k: openai_reply("SYN, SYN-ACK, ACK"))\n    assert svc.solve("CN", q)["source"] == "ai"\n\n\ndef test_vision_request_formats(monkeypatch):\n    sent = {}\n\n    def post(url, json=None, headers=None, timeout=None):\n        sent.update(url=url, body=json, headers=headers)\n        return openai_reply(\'{"answers": []}\') if "anthropic" not in url else Resp(\n            200, {"content": [{"type": "text", "text": "seen"}]})\n    monkeypatch.setattr(L.requests, "post", post)\n    g = LLMClient(provider="gemini", api_key="k")\n    assert g.supports_vision and g.vision_model == g.model\n    assert g.complete_vision("sys", "read this", [("image/jpeg", b"abc")]) == \'{"answers": []}\'\n    parts = sent["body"]["messages"][1]["content"]\n    assert parts[0] == {"type": "text", "text": "read this"}\n    assert parts[1]["image_url"]["url"] == "data:image/jpeg;base64,YWJj" and sent["body"]["temperature"] == 0.0\n    a = LLMClient(provider="anthropic", api_key="k")\n    assert a.complete_vision("sys", "read", [("image/png", b"abc")]) == "seen"\n    blocks = sent["body"]["messages"][0]["content"]\n    assert blocks[0]["source"] == {"type": "base64", "media_type": "image/png", "data": "YWJj"}\n    with pytest.raises(LLMError, match="no image"):\n        g.complete_vision("s", "u", [])\n    with pytest.raises(LLMError, match="no API key"):\n        LLMClient().complete_vision("s", "u", [("image/png", b"x")])\n\n\ndef test_vision_model_choice(monkeypatch):\n    assert LLMClient(provider="groq", api_key="k").vision_model.startswith("meta-llama")\n    assert LLMClient(provider="mistral", api_key="k").vision_model == "pixtral-12b-2409"\n    monkeypatch.setenv("LLM_VISION_MODEL", "my-vision")\n    assert LLMClient(provider="groq", api_key="k").vision_model == "my-vision"\n    assert not LLMClient().supports_vision\n\n\ndef test_fallback_chain_and_model_names(monkeypatch):\n    """A quota error on the first Gemini model moves on to the next model, then to Groq (if it has a key)."""\n    monkeypatch.setenv("GEMINI_API_KEY", "g")\n    monkeypatch.setenv("GROQ_API_KEY", "q")\n    c = LLMClient()\n    assert c.provider == "gemini" and c.model == "gemini-3.8-flash"\n    order = [(x.provider, x.model) for x in c._chain()]\n    assert order[0] == ("gemini", "gemini-3.8-flash") and ("gemini", "gemini-3.5-flash-lite") in order\n    assert order[-1][0] == "groq" or ("groq", "llama-3.3-70b-versatile") in order\n    seen = []\n\n    def post(url, json=None, headers=None, timeout=None):\n        seen.append(json["model"])\n        if "generativelanguage" in url:\n            return Resp(429, {"e": 1})\n        return openai_reply("from groq")\n    monkeypatch.setattr(L.requests, "post", post)\n    assert c.complete("s", "u") == "from groq"\n    assert seen[0] == "gemini-3.8-flash" and seen[-1] == "llama-3.3-70b-versatile"\n    monkeypatch.setattr(L.requests, "post", lambda *a, **k: Resp(429, {"e": 1}))\n    with pytest.raises(LLMError, match="every AI model failed") as e:\n        c.complete("s", "u")\n    assert "429" in str(e.value) and "{" not in str(e.value)               # no raw JSON shown to the student\n\n\ndef test_model_env_variables(monkeypatch):\n    monkeypatch.setenv("GEMINI_API_KEY", "g")\n    monkeypatch.setenv("GROQ_API_KEY", "q")\n    monkeypatch.setenv("LLM_MODEL", "my-gemini")                           # LLM_MODEL = the main provider only\n    monkeypatch.setenv("GROQ_MODEL", "my-groq")\n    assert LLMClient().model == "my-gemini"\n    assert ("groq", "my-groq") in [(x.provider, x.model) for x in LLMClient()._chain()]\n    monkeypatch.setenv("GEMINI_MODEL", "specific")\n    assert LLMClient().model == "specific"\n',
}

EDITS = [
    ('src/inference/solutions.py',
     '"note": f"AI solution failed: {e}" if str(e) else "AI solution failed."}',
     '"note": f"The AI could not write this solution right now: {e}." if str(e) else "The AI could not write this solution right now."}'),
    ('src/inference/solution_jobs.py',
     'MAX_WORKERS = 4 ',
     'MAX_WORKERS = 2 '),
    ('src/inference/solution_jobs.py',
     '" Open this page again to retry.")',
     '" Open this page again in a minute to retry.")'),
    ('app/components/predicted.py',
     'background:var(--blue) !important;opacity:.55;}',
     'background:var(--blue) !important;}'),
    ('app/components/solved.py',
     'padding:.8rem 1rem;opacity:.55;}',
     'padding:.8rem 1rem;}'),
]


def read(path):
    raw = path.read_bytes().decode("utf-8")
    return raw.replace("\r\n", "\n"), "\r\n" in raw


def main():
    if not (ROOT / "src" / "inference" / "generator.py").exists() or not (ROOT / "app" / "pages").exists():
        sys.exit("Run this from the project folder (the one that contains the folders src and app).")
    texts, crlf, problems, notes = {}, {}, [], []
    for rel, old, new in EDITS:
        p = ROOT / rel
        if not p.exists():
            problems.append(f"missing file: {rel}")
            continue
        if rel not in texts:
            texts[rel], crlf[rel] = read(p)
        if new in texts[rel] and old not in texts[rel]:
            notes.append(f"already applied: {rel}")
            continue
        if texts[rel].count(old) != 1:
            problems.append(f"{rel}: expected 1 match, found {texts[rel].count(old)} for: {old[:70]!r}")
            continue
        texts[rel] = texts[rel].replace(old, new)
    for rel in NEW_FILES:
        if (ROOT / rel).exists() and read(ROOT / rel)[0] != NEW_FILES[rel]:
            notes.append(f"will overwrite: {rel}")
    if problems:
        print("NOTHING WAS CHANGED. Problems:")
        for x in problems:
            print("  -", x)
        print("Are you on a branch created from the latest main (git pull first)? Send me this output.")
        sys.exit(1)
    for rel, text in texts.items():
        data = text.replace("\n", "\r\n") if crlf[rel] else text
        (ROOT / rel).write_bytes(data.encode("utf-8"))
    for rel, text in NEW_FILES.items():
        p = ROOT / rel
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(text.encode("utf-8"))
    print(f"Done: {len(texts)} files edited, {len(NEW_FILES)} files created.")
    for n in notes:
        print("  note:", n)
    print("Next: python -m pytest tests -q   (then git add -A, commit, push)")


if __name__ == "__main__":
    main()
